\set ON_ERROR_STOP on
BEGIN;

-- Exact lifecycle-v3 source gate.
SELECT 1/pg_catalog.count(*) AS source_has_no_status_functions FROM (SELECT 1 WHERE pg_catalog.to_regprocedure('agent_private.read_initial_enrollment_grant_status(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz)') IS NULL AND pg_catalog.to_regprocedure('agent_private.read_initial_enrollment_grant_status(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,smallint,timestamptz)') IS NULL) checked;
SELECT 1/pg_catalog.count(*) AS source_has_exact_runtime_reservations FROM (SELECT 1 WHERE
 NOT EXISTS(SELECT 1 FROM agent_private.platform_grant_database_bindings binding WHERE binding.purpose IN('IssueInitialGrant','RevokeInitialGrant') AND NOT agent_private.agent_role_has_capability(binding.login_role,'PlatformGrant','Runtime'))) checked;
WITH login AS(SELECT role.* FROM pg_catalog.pg_roles role WHERE role.rolname=:'agent_platform_grant_role'),
 function_owner AS(SELECT role.* FROM pg_catalog.pg_roles role WHERE role.rolname=:'agent_platform_grant_definer_role'::name),
 table_owner AS(SELECT role.* FROM pg_catalog.pg_roles role WHERE role.rolname=:'agent_table_owner_role'::name),
 schema_info AS(SELECT namespace.oid,namespace.nspowner FROM pg_catalog.pg_namespace namespace WHERE namespace.nspname='agent_private'),
 eligible_logins AS(SELECT role.*,binding.purpose FROM agent_private.platform_grant_database_bindings binding JOIN pg_catalog.pg_roles role ON role.rolname=binding.login_role WHERE binding.purpose IN('IssueInitialGrant','RevokeInitialGrant')),
 current_binding AS(SELECT binding.* FROM agent_private.platform_grant_database_bindings binding WHERE binding.login_role=:'agent_platform_grant_role'::name),
 expected_columns(relname,attname,privilege_type,is_grantable) AS(VALUES
  ('platform_grant_database_bindings','login_role','SELECT',false),('platform_grant_database_bindings','environment_id','SELECT',false),('platform_grant_database_bindings','purpose','SELECT',false),
  ('agent_database_bindings','login_role','SELECT',false),('enrollment_database_bindings','login_role','SELECT',false),('agent_projection_database_bindings','login_role','SELECT',false),
  ('platform_grant_receipts','environment_id','SELECT',false),('platform_grant_receipts','operation_id','SELECT',false),('platform_grant_receipts','grant_id','SELECT',false),('platform_grant_receipts','directory_object_id','SELECT',false),('platform_grant_receipts','device_id','SELECT',false),('platform_grant_receipts','mapping_created_at','SELECT',false),('platform_grant_receipts','token_sha256','SELECT',false),('platform_grant_receipts','authorization_digest','SELECT',false),('platform_grant_receipts','created_at','SELECT',false),('platform_grant_receipts','expires_at','SELECT',false),('platform_grant_receipts','issue_contract_version','SELECT',false),('platform_grant_receipts','mint_permit_not_after','SELECT',false),
  ('platform_grant_receipts','environment_id','INSERT',false),('platform_grant_receipts','operation_id','INSERT',false),('platform_grant_receipts','grant_id','INSERT',false),('platform_grant_receipts','directory_object_id','INSERT',false),('platform_grant_receipts','device_id','INSERT',false),('platform_grant_receipts','mapping_created_at','INSERT',false),('platform_grant_receipts','token_sha256','INSERT',false),('platform_grant_receipts','authorization_digest','INSERT',false),('platform_grant_receipts','created_at','INSERT',false),('platform_grant_receipts','expires_at','INSERT',false),('platform_grant_receipts','issue_contract_version','INSERT',false),('platform_grant_receipts','mint_permit_not_after','INSERT',false),
  ('platform_grant_revocation_receipts','environment_id','SELECT',false),('platform_grant_revocation_receipts','revocation_operation_id','SELECT',false),('platform_grant_revocation_receipts','issue_operation_id','SELECT',false),('platform_grant_revocation_receipts','grant_id','SELECT',false),('platform_grant_revocation_receipts','directory_object_id','SELECT',false),('platform_grant_revocation_receipts','device_id','SELECT',false),('platform_grant_revocation_receipts','mapping_created_at','SELECT',false),('platform_grant_revocation_receipts','token_sha256','SELECT',false),('platform_grant_revocation_receipts','issue_authorization_digest','SELECT',false),('platform_grant_revocation_receipts','issue_created_at','SELECT',false),('platform_grant_revocation_receipts','issue_expires_at','SELECT',false),('platform_grant_revocation_receipts','revoke_authorization_digest','SELECT',false),('platform_grant_revocation_receipts','disposition','SELECT',false),('platform_grant_revocation_receipts','completed_at','SELECT',false),('platform_grant_revocation_receipts','effective_revoked_at','SELECT',false),('platform_grant_revocation_receipts','issue_contract_version','SELECT',false),('platform_grant_revocation_receipts','issue_mint_permit_not_after','SELECT',false),
  ('platform_grant_revocation_receipts','environment_id','INSERT',false),('platform_grant_revocation_receipts','revocation_operation_id','INSERT',false),('platform_grant_revocation_receipts','issue_operation_id','INSERT',false),('platform_grant_revocation_receipts','grant_id','INSERT',false),('platform_grant_revocation_receipts','directory_object_id','INSERT',false),('platform_grant_revocation_receipts','device_id','INSERT',false),('platform_grant_revocation_receipts','mapping_created_at','INSERT',false),('platform_grant_revocation_receipts','token_sha256','INSERT',false),('platform_grant_revocation_receipts','issue_authorization_digest','INSERT',false),('platform_grant_revocation_receipts','issue_created_at','INSERT',false),('platform_grant_revocation_receipts','issue_expires_at','INSERT',false),('platform_grant_revocation_receipts','revoke_authorization_digest','INSERT',false),('platform_grant_revocation_receipts','disposition','INSERT',false),('platform_grant_revocation_receipts','completed_at','INSERT',false),('platform_grant_revocation_receipts','effective_revoked_at','INSERT',false),('platform_grant_revocation_receipts','issue_contract_version','INSERT',false),('platform_grant_revocation_receipts','issue_mint_permit_not_after','INSERT',false),
  ('agent_device_directory_bindings','environment_id','SELECT',false),('agent_device_directory_bindings','directory_object_id','SELECT',false),('agent_device_directory_bindings','device_id','SELECT',false),('agent_device_directory_bindings','created_at','SELECT',false),
  ('devices','environment_id','SELECT',false),('devices','device_id','SELECT',false),('devices','state','SELECT',false),
  ('registrations','environment_id','SELECT',false),('registrations','device_id','SELECT',false),('registrations','state','SELECT',false),
  ('enrollment_requests','environment_id','SELECT',false),('enrollment_requests','device_id','SELECT',false),('enrollment_requests','state','SELECT',false),
  ('enrollment_grants','environment_id','SELECT',false),('enrollment_grants','grant_id','SELECT',false),('enrollment_grants','device_id','SELECT',false),('enrollment_grants','token_sha256','SELECT',false),('enrollment_grants','state','SELECT',false),('enrollment_grants','created_at','SELECT',false),('enrollment_grants','expires_at','SELECT',false),('enrollment_grants','consumed_at','SELECT',false),('enrollment_grants','revoked_at','SELECT',false),
  ('enrollment_grants','state','UPDATE',false),('enrollment_grants','revoked_at','UPDATE',false),
  ('enrollment_grants','environment_id','INSERT',false),('enrollment_grants','grant_id','INSERT',false),('enrollment_grants','device_id','INSERT',false),('enrollment_grants','token_sha256','INSERT',false),('enrollment_grants','state','INSERT',false),('enrollment_grants','created_at','INSERT',false),('enrollment_grants','expires_at','INSERT',false)),
 actual_columns AS(SELECT object.relname,attribute.attname,acl.privilege_type,acl.is_grantable FROM pg_catalog.pg_class object JOIN pg_catalog.pg_attribute attribute ON attribute.attrelid=object.oid,schema_info,function_owner,LATERAL pg_catalog.aclexplode(attribute.attacl) acl WHERE object.relnamespace=schema_info.oid AND acl.grantee=function_owner.oid),
 expected_execute(signature) AS(
  SELECT 'agent_private.audit_platform_grant_privileges(uuid,name,name)'::pg_catalog.regprocedure
  UNION ALL SELECT signature FROM (VALUES('agent_private.issue_initial_enrollment_grant(uuid,uuid,uuid,uuid,timestamptz,bytea,bytea)'::pg_catalog.regprocedure),('agent_private.issue_initial_enrollment_grant(uuid,uuid,uuid,uuid,timestamptz,timestamptz,bytea,bytea)'::pg_catalog.regprocedure)) issue_functions(signature),current_binding WHERE purpose='IssueInitialGrant'
  UNION ALL SELECT signature FROM (VALUES('agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz)'::pg_catalog.regprocedure),('agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,smallint,timestamptz)'::pg_catalog.regprocedure),('agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,bytea)'::pg_catalog.regprocedure),('agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,smallint,timestamptz,bytea)'::pg_catalog.regprocedure)) revoke_functions(signature),current_binding WHERE purpose='RevokeInitialGrant'),
 actual_execute AS(SELECT function.oid::pg_catalog.regprocedure AS signature FROM pg_catalog.pg_proc function,schema_info WHERE function.pronamespace=schema_info.oid AND pg_catalog.has_function_privilege(:'agent_platform_grant_role',function.oid,'EXECUTE')),
 all_functions(signature,purpose) AS(VALUES
  ('agent_private.issue_initial_enrollment_grant(uuid,uuid,uuid,uuid,timestamptz,bytea,bytea)'::pg_catalog.regprocedure,'IssueInitialGrant'),
  ('agent_private.issue_initial_enrollment_grant(uuid,uuid,uuid,uuid,timestamptz,timestamptz,bytea,bytea)'::pg_catalog.regprocedure,'IssueInitialGrant'),
  ('agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz)'::pg_catalog.regprocedure,'RevokeInitialGrant'),
  ('agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,smallint,timestamptz)'::pg_catalog.regprocedure,'RevokeInitialGrant'),
  ('agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,bytea)'::pg_catalog.regprocedure,'RevokeInitialGrant'),
  ('agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,smallint,timestamptz,bytea)'::pg_catalog.regprocedure,'RevokeInitialGrant'),
  ('agent_private.audit_platform_grant_privileges(uuid,name,name)'::pg_catalog.regprocedure,NULL::text)),
 expected_function_acl(signature,grantee,is_grantable) AS(
  SELECT function.signature,function_owner.oid,false FROM all_functions function,function_owner
  UNION ALL SELECT function.signature,eligible.oid,false FROM all_functions function,eligible_logins eligible WHERE function.purpose IS NULL OR function.purpose=eligible.purpose),
 actual_function_acl AS(SELECT function.oid::pg_catalog.regprocedure AS signature,acl.grantee,acl.is_grantable FROM pg_catalog.pg_proc function,schema_info,LATERAL pg_catalog.aclexplode(coalesce(function.proacl,pg_catalog.acldefault('f',function.proowner))) acl WHERE function.pronamespace=schema_info.oid AND function.oid=ANY(ARRAY['agent_private.issue_initial_enrollment_grant(uuid,uuid,uuid,uuid,timestamptz,bytea,bytea)'::pg_catalog.regprocedure,'agent_private.issue_initial_enrollment_grant(uuid,uuid,uuid,uuid,timestamptz,timestamptz,bytea,bytea)'::pg_catalog.regprocedure,'agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz)'::pg_catalog.regprocedure,'agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,smallint,timestamptz)'::pg_catalog.regprocedure,'agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,bytea)'::pg_catalog.regprocedure,'agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,smallint,timestamptz,bytea)'::pg_catalog.regprocedure,'agent_private.audit_platform_grant_privileges(uuid,name,name)'::pg_catalog.regprocedure]::oid[]) AND acl.privilege_type='EXECUTE'),
 expected_policies(relname,polname,polcmd,qual,withcheck) AS(VALUES
  ('platform_grant_database_bindings','platform_grant_definer_select','r','true',NULL::text),
  ('platform_grant_receipts','platform_grant_definer_select','r','true',NULL::text),('platform_grant_receipts','platform_grant_definer_insert','a',NULL::text,'true'),
  ('platform_grant_revocation_receipts','platform_grant_definer_select','r','true',NULL::text),('platform_grant_revocation_receipts','platform_grant_definer_insert','a',NULL::text,'true'),
  ('agent_database_bindings','platform_grant_definer_select','r','true',NULL::text),('enrollment_database_bindings','platform_grant_definer_select','r','true',NULL::text),('agent_projection_database_bindings','platform_grant_definer_select','r','true',NULL::text),
  ('agent_device_directory_bindings','platform_grant_definer_select','r','true',NULL::text),('devices','platform_grant_definer_select','r','true',NULL::text),
  ('registrations','platform_grant_definer_select','r','true',NULL::text),('enrollment_requests','platform_grant_definer_select','r','true',NULL::text),
  ('enrollment_grants','platform_grant_definer_select','r','true',NULL::text),('enrollment_grants','platform_grant_definer_insert','a',NULL::text,'true'),('enrollment_grants','platform_grant_definer_update','w','(state = ''Available''::text)','(state = ''Revoked''::text)')),
 expected_owner_policies(relname) AS(VALUES('platform_grant_database_bindings'),('platform_grant_receipts'),('platform_grant_revocation_receipts')),
 expected_structure_columns(relname,attnum,attname,type_name,not_null) AS(VALUES
  ('platform_grant_database_bindings',1,'login_role','name',true),('platform_grant_database_bindings',2,'environment_id','uuid',true),('platform_grant_database_bindings',3,'purpose','text',true),
  ('platform_grant_receipts',1,'environment_id','uuid',true),('platform_grant_receipts',2,'operation_id','uuid',true),('platform_grant_receipts',3,'grant_id','uuid',true),('platform_grant_receipts',4,'directory_object_id','uuid',true),('platform_grant_receipts',5,'device_id','uuid',true),('platform_grant_receipts',6,'mapping_created_at','timestamp with time zone',true),('platform_grant_receipts',7,'token_sha256','bytea',true),('platform_grant_receipts',8,'authorization_digest','bytea',true),('platform_grant_receipts',9,'created_at','timestamp with time zone',true),('platform_grant_receipts',10,'expires_at','timestamp with time zone',true),('platform_grant_receipts',11,'issue_contract_version','smallint',true),('platform_grant_receipts',12,'mint_permit_not_after','timestamp with time zone',false),
  ('platform_grant_revocation_receipts',1,'environment_id','uuid',true),('platform_grant_revocation_receipts',2,'revocation_operation_id','uuid',true),('platform_grant_revocation_receipts',3,'issue_operation_id','uuid',true),('platform_grant_revocation_receipts',4,'grant_id','uuid',true),('platform_grant_revocation_receipts',5,'directory_object_id','uuid',true),('platform_grant_revocation_receipts',6,'device_id','uuid',true),('platform_grant_revocation_receipts',7,'mapping_created_at','timestamp with time zone',true),('platform_grant_revocation_receipts',8,'token_sha256','bytea',true),('platform_grant_revocation_receipts',9,'issue_authorization_digest','bytea',true),('platform_grant_revocation_receipts',10,'issue_created_at','timestamp with time zone',true),('platform_grant_revocation_receipts',11,'issue_expires_at','timestamp with time zone',true),('platform_grant_revocation_receipts',12,'revoke_authorization_digest','bytea',true),('platform_grant_revocation_receipts',13,'disposition','text',true),('platform_grant_revocation_receipts',14,'completed_at','timestamp with time zone',true),('platform_grant_revocation_receipts',15,'effective_revoked_at','timestamp with time zone',false),('platform_grant_revocation_receipts',16,'issue_contract_version','smallint',true),('platform_grant_revocation_receipts',17,'issue_mint_permit_not_after','timestamp with time zone',false)),
 actual_structure_columns AS(SELECT object.relname,attribute.attnum::integer,attribute.attname,pg_catalog.format_type(attribute.atttypid,attribute.atttypmod),attribute.attnotnull FROM pg_catalog.pg_class object JOIN pg_catalog.pg_attribute attribute ON attribute.attrelid=object.oid,schema_info WHERE object.relnamespace=schema_info.oid AND object.relname IN('platform_grant_database_bindings','platform_grant_receipts','platform_grant_revocation_receipts') AND attribute.attnum>0 AND NOT attribute.attisdropped),
 expected_owned_functions(signature) AS(VALUES
  ('agent_private.issue_initial_enrollment_grant(uuid,uuid,uuid,uuid,timestamptz,bytea,bytea)'::pg_catalog.regprocedure),
  ('agent_private.issue_initial_enrollment_grant(uuid,uuid,uuid,uuid,timestamptz,timestamptz,bytea,bytea)'::pg_catalog.regprocedure),
  ('agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz)'::pg_catalog.regprocedure),
  ('agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,smallint,timestamptz)'::pg_catalog.regprocedure),
  ('agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,bytea)'::pg_catalog.regprocedure),
  ('agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,smallint,timestamptz,bytea)'::pg_catalog.regprocedure),
  ('agent_private.audit_platform_grant_privileges(uuid,name,name)'::pg_catalog.regprocedure)),
 actual_owned_functions(signature) AS(SELECT function.oid::pg_catalog.regprocedure FROM pg_catalog.pg_proc function,schema_info,function_owner WHERE function.pronamespace=schema_info.oid AND function.proowner=function_owner.oid),
 checks AS(SELECT
  (SELECT pg_catalog.count(*)=1 FROM login) AND (SELECT pg_catalog.count(*)=1 FROM function_owner) AND (SELECT pg_catalog.count(*)=1 FROM table_owner) AND
  agent_private.agent_role_has_capability(:'agent_platform_grant_role'::name,'PlatformGrant','Runtime') AND
  agent_private.agent_role_has_capability(:'agent_platform_grant_definer_role'::name,'PlatformGrant','Definer') AND
  COALESCE((SELECT helper.proowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=:'agent_table_owner_role'::name) AND helper.prosecdef AND helper.prolang=(SELECT oid FROM pg_catalog.pg_language WHERE lanname='sql') AND helper.prokind='f' AND NOT helper.proretset AND helper.prorettype='boolean'::pg_catalog.regtype AND helper.proargnames=ARRAY['p_role','p_capability','p_role_kind']::text[] AND helper.proconfig=ARRAY['search_path=pg_catalog, agent_private, pg_temp']::text[] AND pg_catalog.btrim(helper.prosrc,E' \t\r\n')=pg_catalog.btrim(' SELECT p_capability IS NOT NULL AND p_role_kind IN(''Runtime'',''Definer'') AND EXISTS(SELECT 1 FROM agent_private.agent_capability_roles reservation
        WHERE reservation.role_name=p_role AND reservation.capability=p_capability AND reservation.role_kind=p_role_kind) AND
        COALESCE((SELECT registry.relowner=namespace.nspowner AND registry.relrowsecurity AND registry.relforcerowsecurity AND
          NOT EXISTS(SELECT 1 FROM pg_catalog.aclexplode(COALESCE(registry.relacl,pg_catalog.acldefault(''r'',registry.relowner))) acl WHERE acl.grantee<>registry.relowner) AND
          NOT EXISTS(SELECT 1 FROM pg_catalog.pg_attribute attribute,LATERAL pg_catalog.aclexplode(attribute.attacl) acl WHERE attribute.attrelid=registry.oid AND acl.grantee<>registry.relowner) AND
          (SELECT pg_catalog.count(*)=1 AND pg_catalog.bool_and(policy.polname=''definer_all'' AND policy.polcmd=''*'' AND policy.polpermissive AND policy.polroles=ARRAY[registry.relowner]::oid[] AND pg_catalog.pg_get_expr(policy.polqual,policy.polrelid)=''true'' AND pg_catalog.pg_get_expr(policy.polwithcheck,policy.polrelid)=''true'') FROM pg_catalog.pg_policy policy WHERE policy.polrelid=registry.oid) AND
          (SELECT pg_catalog.count(*)=1 AND pg_catalog.bool_and(constraint_info.conkey=ARRAY[1]::smallint[]) FROM pg_catalog.pg_constraint constraint_info WHERE constraint_info.conrelid=registry.oid AND constraint_info.contype=''p'') AND
          NOT EXISTS(SELECT role_name FROM agent_private.agent_capability_roles GROUP BY role_name HAVING pg_catalog.count(*)<>1) AND
          NOT EXISTS(SELECT 1 FROM agent_private.agent_capability_roles registered LEFT JOIN pg_catalog.pg_roles role ON role.rolname=registered.role_name WHERE role.oid IS NULL OR role.oid=registry.relowner OR registered.role_kind NOT IN(''Runtime'',''Definer'') OR
           (registered.role_kind=''Runtime'' AND (NOT role.rolcanlogin OR role.rolsuper OR role.rolbypassrls OR role.rolcreatedb OR role.rolcreaterole OR role.rolinherit OR role.rolreplication)) OR
           (registered.role_kind=''Definer'' AND (role.rolcanlogin OR role.rolsuper OR role.rolbypassrls OR role.rolcreatedb OR role.rolcreaterole OR role.rolinherit OR role.rolreplication)) OR
           EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members member WHERE member.member=role.oid OR member.roleid=role.oid))
         FROM pg_catalog.pg_class registry JOIN pg_catalog.pg_namespace namespace ON namespace.oid=registry.relnamespace
         WHERE registry.oid=pg_catalog.to_regclass(''agent_private.agent_capability_roles'')),false) AND
        NOT EXISTS(
         (SELECT acl.grantee,acl.is_grantable,acl.privilege_type FROM pg_catalog.pg_proc helper,
           LATERAL pg_catalog.aclexplode(COALESCE(helper.proacl,pg_catalog.acldefault(''f'',helper.proowner))) acl
          WHERE helper.oid=pg_catalog.to_regprocedure(''agent_private.agent_role_has_capability(name,text,text)'')
          EXCEPT
          SELECT role.oid,false,''EXECUTE''::text FROM pg_catalog.pg_roles role
          WHERE role.oid=(SELECT helper.proowner FROM pg_catalog.pg_proc helper WHERE helper.oid=pg_catalog.to_regprocedure(''agent_private.agent_role_has_capability(name,text,text)''))
             OR EXISTS(SELECT 1 FROM agent_private.agent_capability_roles reservation WHERE reservation.role_name=role.rolname::name AND reservation.role_kind=''Definer''))
         UNION ALL
         (SELECT role.oid,false,''EXECUTE''::text FROM pg_catalog.pg_roles role
          WHERE role.oid=(SELECT helper.proowner FROM pg_catalog.pg_proc helper WHERE helper.oid=pg_catalog.to_regprocedure(''agent_private.agent_role_has_capability(name,text,text)''))
             OR EXISTS(SELECT 1 FROM agent_private.agent_capability_roles reservation WHERE reservation.role_name=role.rolname::name AND reservation.role_kind=''Definer'')
          EXCEPT
          SELECT acl.grantee,acl.is_grantable,acl.privilege_type FROM pg_catalog.pg_proc helper,
           LATERAL pg_catalog.aclexplode(COALESCE(helper.proacl,pg_catalog.acldefault(''f'',helper.proowner))) acl
          WHERE helper.oid=pg_catalog.to_regprocedure(''agent_private.agent_role_has_capability(name,text,text)'')));',E' \t\r\n') FROM pg_catalog.pg_proc helper WHERE helper.oid=pg_catalog.to_regprocedure('agent_private.agent_role_has_capability(name,text,text)')),false) AND
  NOT EXISTS(SELECT 1 FROM login WHERE NOT rolcanlogin OR rolsuper OR rolbypassrls OR rolcreatedb OR rolcreaterole OR rolinherit OR rolreplication) AND
  NOT EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members member,login WHERE member.member=login.oid OR member.roleid=login.oid) AND
  NOT EXISTS(SELECT 1 FROM pg_catalog.pg_database database,login WHERE database.datdba=login.oid) AND
  NOT EXISTS(SELECT 1 FROM pg_catalog.pg_namespace namespace,login WHERE namespace.nspowner=login.oid) AND
  NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class object,login WHERE object.relowner=login.oid) AND
  NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc function,login WHERE function.proowner=login.oid) AND
  NOT EXISTS(SELECT 1 FROM agent_private.agent_database_bindings binding WHERE binding.login_role=:'agent_platform_grant_role'::name) AND
  NOT EXISTS(SELECT 1 FROM agent_private.enrollment_database_bindings binding WHERE binding.login_role=:'agent_platform_grant_role'::name) AND
  NOT EXISTS(SELECT 1 FROM agent_private.agent_projection_database_bindings binding WHERE binding.login_role=:'agent_platform_grant_role'::name) AND
